GRANT INSERT ON public.pending_projects TO anon,authenticated; GRANT ALL ON public.pending_projects TO service_role;
ALTER TABLE public.pending_projects ENABLE ROW LEVEL SECURITY; CREATE POLICY pending_projects_insert_anyone ON public.pending_projects FOR INSERT TO anon,authenticated WITH CHECK(true);
CREATE INDEX pending_projects_email_unclaimed_idx ON public.pending_projects(lower(btrim(email))) WHERE claimed_at IS NULL;
CREATE FUNCTION public.claim_pending_projects() RETURNS TABLE(job_id uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE caller_id uuid:=auth.uid(); caller_email text; rec record; new_job_id uuid; BEGIN IF caller_id IS NULL THEN RETURN; END IF; SELECT lower(btrim(u.email)) INTO caller_email FROM auth.users u WHERE u.id=caller_id AND u.email_confirmed_at IS NOT NULL; IF caller_email IS NULL OR caller_email='' THEN RETURN; END IF; FOR rec IN SELECT * FROM public.pending_projects p WHERE lower(btrim(p.email))=caller_email AND p.claimed_at IS NULL ORDER BY p.created_at,p.id FOR UPDATE SKIP LOCKED LOOP INSERT INTO public.jobs(owner_id,title,description,trade,estimated_budget,location_zip,city,language,urgency,status,media_keys) VALUES(caller_id,rec.title,rec.description,rec.trade,rec.estimated_budget,rec.location_zip,rec.city,coalesce(rec.language,'de'),coalesce(rec.urgency,'normal'),'open',coalesce(rec.media_keys,'{}')) RETURNING id INTO new_job_id; UPDATE public.pending_projects SET claimed_at=now(),claimed_job_id=new_job_id WHERE id=rec.id; job_id:=new_job_id; RETURN NEXT; END LOOP; END; $$;
REVOKE EXECUTE ON FUNCTION public.claim_pending_projects() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.claim_pending_projects() TO authenticated;
