CREATE FUNCTION public.is_verified_contractor(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.contractors WHERE user_id=_user_id AND verified) OR public.has_role(_user_id,'admin') $$;
