CREATE POLICY network_members_select ON public.network_thread_members FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_network_thread_member(thread_id,auth.uid())); CREATE POLICY network_members_insert_creator ON public.network_thread_members FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.network_threads t WHERE t.id=thread_id AND t.created_by=auth.uid())); CREATE POLICY network_members_delete_self ON public.network_thread_members FOR DELETE TO authenticated USING(user_id=auth.uid());
