ALTER TABLE public.verifications ENABLE ROW LEVEL SECURITY; CREATE POLICY verifications_select ON public.verifications FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY verifications_insert ON public.verifications FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending_review'); CREATE POLICY verifications_review ON public.verifications FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin')); CREATE POLICY verifications_delete ON public.verifications FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.calendar_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,title text NOT NULL,notes text,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,event_type text NOT NULL DEFAULT 'job',linked_job_id uuid,linked_match_id uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.calendar_events TO authenticated; GRANT ALL ON public.calendar_events TO service_role;
ALTER TABLE public.calendar_events ENABLE ROW LEVEL SECURITY; CREATE POLICY calendar_own ON public.calendar_events FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.match_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),match_id uuid NOT NULL,contractor_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,net_amount_cents integer NOT NULL DEFAULT 0,platform_fee_bps integer NOT NULL DEFAULT 500,promotional_discount_cents integer NOT NULL DEFAULT 0,final_due_cents integer NOT NULL DEFAULT 0,promo_code text,status text NOT NULL DEFAULT 'open',paid_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(match_id,contractor_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.match_invoices TO authenticated; GRANT ALL ON public.match_invoices TO service_role;
ALTER TABLE public.match_invoices ENABLE ROW LEVEL SECURITY; CREATE POLICY match_invoices_own ON public.match_invoices FOR ALL TO authenticated USING(contractor_id=auth.uid()) WITH CHECK(contractor_id=auth.uid());
CREATE TABLE public.profile_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,reported_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,reason text NOT NULL,notes text,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profile_reports TO authenticated; GRANT ALL ON public.profile_reports TO service_role;
ALTER TABLE public.profile_reports ENABLE ROW LEVEL SECURITY; CREATE POLICY reports_select ON public.profile_reports FOR SELECT TO authenticated USING(reporter_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY reports_insert ON public.profile_reports FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid() AND reporter_id<>reported_id); CREATE POLICY reports_review ON public.profile_reports FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['services','homeowners','team_members','jobs','matches','bookings','clients','invoices','receipts','finanz_settings','staff_hours','verifications'] LOOP EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.set_updated_at()',t||'_set_updated_at',t); END LOOP; END $$;